//! Differential test: line-line `crosses` against GEOS (via shapely) on 600 pairs of short
//! polylines on a grid, so that they share vertices, cross, touch, and overlap. Reference values
//! are in `tests/fixtures/geos_line_line.csv`, generated by `generate_line_line_pairs.py`.

use std::path::PathBuf;

use tpt_gis_geom::line_relate::linestrings_cross;
use tpt_gis_geom::line_string::LineString;
use tpt_gis_geom::Point;

fn parse_points(text: &str) -> Vec<Point> {
    text.split_whitespace()
        .map(|pair| {
            let (x, y) = pair.split_once(',').unwrap();
            Point::new(x.parse().unwrap(), y.parse().unwrap())
        })
        .collect()
}

#[test]
fn line_line_crosses_agrees_with_geos() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/geos_line_line.csv");
    let text = std::fs::read_to_string(path).unwrap();
    let mut checked = 0;
    let mut positives = 0;
    let mut mismatches = Vec::new();
    for (index, row) in text.lines().enumerate() {
        if row.starts_with('#') || row.trim().is_empty() {
            continue;
        }
        let f: Vec<&str> = row.split(';').collect();
        let a_points = parse_points(f[0]);
        let b_points = parse_points(f[1]);
        let want = f[2] == "1";
        let got = linestrings_cross(&LineString::new(&a_points), &LineString::new(&b_points));
        if got {
            positives += 1;
        }
        if got != want {
            mismatches.push(format!("row {}: ours {got}, GEOS {want}", index + 1));
        }
        checked += 1;
    }
    assert!(checked >= 600, "only {checked} rows");
    assert!(positives > 50, "only {positives} crossings in the fixture");
    assert!(
        mismatches.is_empty(),
        "{} disagreements with GEOS:\n{}",
        mismatches.len(),
        mismatches.iter().take(20).cloned().collect::<Vec<_>>().join("\n")
    );
}
